import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test(
    "The same vendor name is allowed in a different tenant",
    { tag: "@VEN-04" },
    async ({ apiAs }) => {
      // Arrange: a vendor with the same name already exists in another tenant (Globex).
      // The name is made unique so parallel runs don't collide on the shared database.
      const vendorName = uniqueName("Acme Freight");
      const globex = await apiAs("otherTenant");
      const existing = await globex.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });
      expect(existing.status(), "seed vendor in Globex tenant").toBe(201);

      // Act: the Northwind member creates a vendor with that same name.
      const northwind = await apiAs("member");
      const response = await northwind.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Assert
      expect(response.status()).toBe(201);
      const vendor = await response.json();
      expect(vendor.id).toBeTruthy();
      expect(vendor.name).toBe(vendorName);
      expect(vendor.category).toBe("logistics");
    },
  );
});
